//! Rust provider vs the TypeScript oracle.
//!
//! Fixture: `tests/fixtures/aero-oracle-parity.json`, generated by
//! `scripts/export-oracle-parity-fixture.mjs` in the research repo from three
//! **self-owned synthetic designs** (no vendor geometry, no engine-derived
//! data). It carries the serialized calibrated designs and the TS oracle's
//! answers for 12 Mach x 3 alpha x 2 methods per design (216 points).
//!
//! Tier: both implementations are IEEE-754 f64 and the Rust module mirrors the
//! TS arithmetic order, so the bound is floating-point sized. Observed worst
//! residual: 2.2e-16 (1 ulp); the assertion uses the G2 tier, 1e-15.

mod common;

use astraea_core::calibrated::{evaluate, CpMethod, EvalOptions};
use common::{design_from_json, num, text};
use serde_json::Value;

#[test]
fn rust_provider_reproduces_the_ts_oracle() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/aero-oracle-parity.json"))
        .expect("fixture json");
    let designs: Vec<_> = fixture["designs"]
        .as_array()
        .expect("designs")
        .iter()
        .map(|design| design_from_json(&design.to_string()))
        .collect();
    let points = fixture["points"].as_array().expect("points");
    assert_eq!(points.len(), 216, "expected the 216-point sweep");

    let mut worst = 0.0_f64;
    let mut worst_at = String::new();
    for p in points {
        let design = &designs[p["design"].as_u64().expect("design index") as usize];
        let method = if text(p, "method") == "rogers" { CpMethod::Rogers } else { CpMethod::Barrowman };
        let options = EvalOptions {
            mach: num(p, "mach"),
            alpha_deg: num(p, "alpha"),
            method,
            nozzle_exit_in: Some(0.0),
            altitude_ft: Some(0.0),
            site: None,
        };
        let got = evaluate(design, &options).expect("evaluate");
        let where_ = format!(
            "design {} {} M{} a{}",
            p["design"], text(p, "method"), num(p, "mach"), num(p, "alpha")
        );
        for (name, actual, expected) in [
            ("cd", got.cd, num(p, "cd")),
            ("cdPowerOff", got.cd_power_off, num(p, "cdPowerOff")),
            ("cdPowerOn", got.cd_power_on, num(p, "cdPowerOn")),
            ("cl", got.cl, num(p, "cl")),
            ("cn", got.cn, num(p, "cn")),
            ("cnPotential", got.cn_potential, num(p, "cnPotential")),
            ("cnViscous", got.cn_viscous, num(p, "cnViscous")),
            ("cnAlpha04", got.cn_alpha04, num(p, "cnAlpha04")),
            ("cpIn", got.cp_in, num(p, "cpIn")),
            ("cp04In", got.cp04_in, num(p, "cp04In")),
            ("reynolds", got.reynolds, num(p, "reynolds")),
        ] {
            let rel = (actual - expected).abs() / expected.abs().max(1e-3);
            if rel > worst {
                worst = rel;
                worst_at = format!("{name} at {where_}: {actual} vs {expected}");
            }
        }
    }
    println!("worst TS-oracle residual: {worst:e} ({worst_at})");
    assert!(
        worst <= 1e-15,
        "TS oracle residual {worst:e} at {worst_at} exceeds 1e-15"
    );
}
